import csv


def lire(lignes):
    eleves = []
    for ligne in csv.DictReader(lignes, delimiter=";"):
        try:
            sommeil, note = float(ligne["sommeil"]), float(ligne["note"])
        except ValueError:
            continue
        if 0 < sommeil <= 24 and 0 <= note <= 20:
            eleves.append({"sommeil": sommeil, "note": note, "transport": ligne["transport"]})
    return eleves


import statistics


def rapport(lignes):
    eleves = lire(lignes)
    xs = [e["sommeil"] for e in eleves]
    ys = [e["note"] for e in eleves]
    mx, my = statistics.mean(xs), statistics.mean(ys)
    cov = sum((x - mx) * (y - my) for x, y in zip(xs, ys)) / len(xs)
    r = cov / (statistics.pstdev(xs) * statistics.pstdev(ys))
    pied = sum(1 for e in eleves if e["transport"] == "pied")
    return {"effectif": len(eleves), "lignes_ecartees": len(lignes) - 1 - len(eleves), "r_sommeil_note": round(r, 2), "part_pied": round(pied / len(eleves), 2)}
